"""Generate exact integer brackets; native tests certify every endpoint."""

import math
from pathlib import Path


def generate():
    lines = [
        "// Exact integer brackets for 256 normalized-mantissa bins: k=70, then k=71.",
        "// Generated by tests/gemma4_gpu/generate_norm_intervals.py.",
    ]
    for power in (70, 71):
        target = 1 << power
        for index in range(256):
            first = (1 << 23) + (index << 15)
            last = first + (1 << 15) - 1
            lower = math.isqrt(target // last)
            upper = math.isqrt(target // first)
            if first * upper * upper < target:
                upper += 1
            lines.append(f"{{0x{lower:08x}U, 0x{upper:08x}U}},")
    root = Path(__file__).resolve().parents[2]
    destination = root / "src/gemma4/kernels/norm_intervals.inc"
    with destination.open("w", encoding="utf-8", newline="\n") as output:
        output.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    generate()
